// 1. Load config
$config_path = __DIR__ . '/config/config.php';
if (!file_exists($config_path)) {
    echo '<div class="p-4 mb-6 bg-red-50 text-red-700 rounded-xl border border-red-200 flex items-start gap-3">
        <i class="fas fa-exclamation-circle mt-0.5"></i>
