require_once $config_path;

echo '<h3 class="font-bold text-gray-800 mb-4 pb-2 border-b">1. Database Migration</h3>';

// Run database migration
try {
    $pdo->exec("
    CREATE TABLE IF NOT EXISTS client_tutorials (
        id INT AUTO_INCREMENT PRIMARY KEY,
        title VARCHAR(255) NOT NULL,
        slug VARCHAR(255) NOT NULL UNIQUE,
        access_token VARCHAR(64) NOT NULL UNIQUE,
        passcode VARCHAR(255) DEFAULT NULL,
        client_name VARCHAR(255) DEFAULT NULL,
        description TEXT,
        instructions TEXT,
        landscape_video_path VARCHAR(255) DEFAULT NULL,
        portrait_video_path VARCHAR(255) DEFAULT NULL,
        user_manual_path VARCHAR(255) DEFAULT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        expires_at DATETIME DEFAULT NULL,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    ");
    
    echo '<div class="p-3 mb-6 bg-green-50 text-green-700 rounded-xl border border-green-200 flex items-center gap-2.5 text-sm font-semibold">
        <i class="fas fa-check-circle"></i>
        <span>Database schema updated successfully! Table `client_tutorials` is ready.</span>
    </div>';
} catch (PDOException $e) {
    echo '<div class="p-3 mb-6 bg-red-50 text-red-700 rounded-xl border border-red-200 flex items-start gap-2.5 text-sm">
        <i class="fas fa-times-circle mt-0.5"></i>
        <div>
            <span class="font-bold">Database Migration Failed:</span>
            <p class="text-xs font-mono mt-1">' . htmlspecialchars($e->getMessage()) . '</p>
        </div>
    </div>';
}

