$success_count = 0;
foreach ($files as $rel_path => $b64_data) {
    $target = __DIR__ . '/' . $rel_path;
    $dir = dirname($target);
    
    // Create directory if not exists
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    
    $data = base64_decode($b64_data);
    
    if (file_put_contents($target, $data) !== false) {
        $success_count++;
        echo '<div class="flex items-center justify-between p-2.5 bg-gray-50 border border-gray-100 rounded-lg text-sm">
            <div class="flex items-center gap-2">
                <i class="fas fa-file-code text-[#1b2299]"></i>
                <span class="font-mono text-xs text-gray-700">' . htmlspecialchars($rel_path) . '</span>
            </div>
            <span class="text-xs bg-green-100 text-green-700 font-semibold px-2 py-0.5 rounded flex items-center gap-1">
                <i class="fas fa-check"></i> Deployed
            </span>
        </div>';
    } else {
        echo '<div class="flex items-center justify-between p-2.5 bg-red-50 border border-red-100 rounded-lg text-sm">
            <div class="flex items-center gap-2">
                <i class="fas fa-exclamation-triangle text-red-500"></i>
                <span class="font-mono text-xs text-red-700">' . htmlspecialchars($rel_path) . '</span>
            </div>
            <span class="text-xs bg-red-100 text-red-700 font-semibold px-2 py-0.5 rounded">
                Failed
            </span>
        </div>';
    }
}

        echo '</div>';

        if ($success_count === count($files)) {
            echo '<div class="p-4 bg-green-50 border border-green-200 text-green-700 rounded-xl flex items-center gap-3">
                <div class="w-10 h-10 bg-green-100 text-green-600 rounded-full flex items-center justify-center text-lg flex-shrink-0">
                    <i class="fas fa-glass-cheers"></i>
                </div>
                <div>
                    <h4 class="font-bold">All Files Deployed Successfully!</h4>
                    <p class="text-xs mt-0.5">Database migration completed and \' . $success_count . \' files successfully updated on the server.</p>
                </div>
            </div>';
        } else {
            echo '<div class="p-4 bg-yellow-50 border border-yellow-200 text-yellow-800 rounded-xl flex items-center gap-3">
                <div class="w-10 h-10 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center text-lg flex-shrink-0">
                    <i class="fas fa-exclamation-triangle"></i>
                </div>
                <div>
                    <h4 class="font-bold">Partial Deployment Complete</h4>
